-- Description: Processe the event ID 22 race results

SET SCHEMA endurancetrio_hub;

-- Update existing race's result_status
UPDATE race SET race_status = 'COMPLETED', result_status = 'COMPLETE' WHERE id IN (82, 83, 84, 85, 86);

-- Update existing athletes
UPDATE athlete SET long_name = 'João M. Lopes', known_name = 'João M. Lopes' WHERE id = 681;

-- Insert new athletes

ALTER SEQUENCE endurancetrio_hub.seq_athlete_id RESTART WITH 727;

-- Update existing teams
UPDATE team SET full_name = 'Atlético Algés', short_name = 'Atlético Algés' WHERE id = 65;
UPDATE team SET full_name = 'Escola Naval', short_name = 'Escola Naval' WHERE id = 70;

-- Insert new teams

ALTER SEQUENCE endurancetrio_hub.seq_team_id RESTART WITH 98;

-- Insert individual results

ALTER SEQUENCE endurancetrio_hub.seq_individual_result_id RESTART WITH 3073;

-- Insert team results

ALTER SEQUENCE endurancetrio_hub.seq_team_result_id RESTART WITH 73;

